#!/usr/bin/env node
/**
 * Canonical PAAIPE logo gate (Frontend Master Command, Tab 02).
 *
 * Two things are checked, because there are two kinds of file:
 *
 *  1. public/brand/*.png - the CANONICAL originals supplied by PAAIPE. These
 *     must match their SHA-256 exactly. Any re-encode, optimiser pass, crop,
 *     recolour or regeneration changes the bytes and fails.
 *
 *  2. public/brand/renditions/*.png - proportional downscales generated by
 *     scripts/generate-logo-renditions.mjs. These are gated on exact pixel
 *     dimensions and a per-file byte ceiling rather than a hash, because PNG
 *     encoder output is not stable across sharp/libvips versions. The artwork
 *     is never altered; only the pixel count changes.
 *
 * An UNEXPECTED file in either directory fails, so an alternate, recreated or
 * recoloured logo cannot be slipped in beside the approved one.
 *
 * PROVENANCE OF THE PINNED HASHES
 * -------------------------------
 * The master command PDF prints a different pair of hashes. On 2026-09-03 the
 * owner ruled that the supplied files are the logos to be used, so the PDF's
 * checksums are stale and the pins below - measured from the supplied files -
 * are authoritative. The superseded pair is kept in SUPERSEDED_SHA256 so the
 * divergence stays on the record rather than disappearing.
 * See docs/frontend-audit.md, B-1.
 */
import { createHash } from 'node:crypto';
import { readdir, readFile, stat } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import sharp from 'sharp';
import { RENDITIONS, webpName } from './generate-logo-renditions.mjs';

const BRAND = new URL('../public/brand/', import.meta.url);
const OUT = new URL('renditions/', BRAND);

/** Measured from the owner-confirmed official files; authoritative since 2026-09-03. */
const CANONICAL = {
  'PAAIPE_Logo_Square_Final.png':
    '88f91f0e5b4a7bf70d202d49dadedae5a677a72c02f9d4eaf097962a247d1867',
  'PAAIPE_Logo_Horizontal_Final.png':
    'f332dc8c5d005b4cf46b06643d005d90071b36072c17a816107f3730021a1378',
};

/** As printed in the master command Tab 02 / Tab 15. Superseded by owner ruling. */
const SUPERSEDED_SHA256 = {
  'PAAIPE_Logo_Square_Final.png':
    'fd142bbe87429931b8cbf10d4f834d24f538b713b79a2fa69fdc660f016adf77',
  'PAAIPE_Logo_Horizontal_Final.png':
    '1e87fd4cbc683de75e240c8810c6f835928e768e849c0ddf2c92866808b55944',
};

/** Tab 14 image budget. No single delivered image may exceed this. */
const MAX_RENDITION_BYTES = 250 * 1024;

const IGNORED = new Set(['.gitkeep', '.DS_Store', 'README.md']);

const failures = [];

async function verifyCanonical() {
  const entries = (await readdir(fileURLToPath(BRAND), { withFileTypes: true })).filter(
    (entry) => !IGNORED.has(entry.name),
  );

  for (const entry of entries) {
    if (entry.isDirectory()) {
      if (entry.name !== 'renditions') {
        failures.push(`public/brand/${entry.name}/: unexpected directory`);
      }
      continue;
    }
    const expected = CANONICAL[entry.name];
    if (!expected) {
      failures.push(
        `public/brand/${entry.name}: unexpected file (only canonical logo files may live here)`,
      );
      continue;
    }
    const actual = createHash('sha256')
      .update(await readFile(new URL(entry.name, BRAND)))
      .digest('hex');
    if (actual !== expected) {
      failures.push(
        `public/brand/${entry.name}: SHA-256 mismatch\n        expected ${expected}\n        actual   ${actual}`,
      );
    } else {
      console.log(`OK    ${entry.name}  ${actual}`);
    }
  }

  for (const name of Object.keys(CANONICAL)) {
    if (!entries.some((entry) => entry.name === name)) {
      failures.push(`public/brand/${name}: missing`);
    }
  }
}

/**
 * A lossless WebP twin must not alter the artwork. It is NOT byte-identical to
 * the PNG when read as raw RGBA, and that is not a defect: fully transparent
 * pixels carry arbitrary RGB in a PNG, and WebP is free to store different
 * values there. Measured on all four twins, the RGB deltas are confined
 * entirely to alpha-0 pixels - the alpha channel matches exactly, and every
 * pixel with any opacity at all matches exactly.
 *
 * So the assertion is written on what can actually be SEEN. A naive
 * `buffer.equals` comparison would fail here for a reason that has nothing to
 * do with the artwork.
 */
async function assertVisiblyIdentical(pngFile, webpFile, label) {
  const png = await sharp(await readFile(pngFile))
    .ensureAlpha()
    .raw()
    .toBuffer();
  const webp = await sharp(await readFile(webpFile))
    .ensureAlpha()
    .raw()
    .toBuffer();
  if (png.length !== webp.length) {
    failures.push(`renditions/${label}: pixel buffer size differs from the PNG`);
    return;
  }
  let alphaDelta = 0;
  let visibleDelta = 0;
  for (let i = 0; i < png.length; i += 4) {
    alphaDelta = Math.max(alphaDelta, Math.abs(png[i + 3] - webp[i + 3]));
    if (png[i + 3] === 0) continue;
    for (let channel = 0; channel < 3; channel += 1) {
      visibleDelta = Math.max(visibleDelta, Math.abs(png[i + channel] - webp[i + channel]));
    }
  }
  if (alphaDelta !== 0) {
    failures.push(`renditions/${label}: alpha channel differs from the PNG (worst ${alphaDelta})`);
  }
  if (visibleDelta !== 0) {
    failures.push(
      `renditions/${label}: visible pixels differ from the PNG (worst ${visibleDelta}). ` +
        `The WebP twin must be LOSSLESS - a lossy encode alters the approved artwork.`,
    );
  }
}

async function verifyRenditions() {
  const expected = new Map();
  for (const rendition of RENDITIONS) {
    expected.set(rendition.name, rendition);
    if (rendition.webp) expected.set(webpName(rendition.name), rendition);
  }
  let entries;
  try {
    entries = await readdir(fileURLToPath(OUT));
  } catch {
    failures.push('public/brand/renditions/ does not exist - run npm run brand:renditions');
    return;
  }

  for (const name of entries.filter((n) => !IGNORED.has(n))) {
    const spec = expected.get(name);
    if (!spec) {
      failures.push(`public/brand/renditions/${name}: unexpected file`);
      continue;
    }
    const file = new URL(name, OUT);
    const { size } = await stat(file);
    const meta = await sharp(await readFile(file)).metadata();

    if (meta.width !== spec.width || meta.height !== spec.height) {
      failures.push(
        `renditions/${name}: ${meta.width}x${meta.height}, expected ${spec.width}x${spec.height}`,
      );
      continue;
    }
    if (size > MAX_RENDITION_BYTES) {
      failures.push(
        `renditions/${name}: ${(size / 1024).toFixed(1)} KiB exceeds the ${MAX_RENDITION_BYTES / 1024} KiB image budget`,
      );
      continue;
    }
    if (name.endsWith('.webp')) {
      await assertVisiblyIdentical(new URL(spec.name, OUT), file, name);
    }
    console.log(
      `OK    renditions/${name}  ${meta.width}x${meta.height}  ${(size / 1024).toFixed(1)} KiB`,
    );
  }

  for (const name of expected.keys()) {
    if (!entries.includes(name)) failures.push(`renditions/${name}: missing`);
  }
}

await verifyCanonical();
await verifyRenditions();

if (failures.length > 0) {
  console.error(`\nFAIL  ${failures.length} brand asset problem(s):`);
  for (const failure of failures) console.error(`    - ${failure}`);
  process.exit(1);
}

console.log('\nPASS  Canonical logos match their pinned SHA-256; every rendition is');
console.log('      the exact declared size and within the image budget.');

const superseded = Object.keys(CANONICAL).filter((n) => CANONICAL[n] !== SUPERSEDED_SHA256[n]);
if (superseded.length > 0) {
  console.log(
    `\nNOTE  ${superseded.length} file(s) differ from the checksums printed in the master command.`,
  );
  console.log('      Superseded by owner ruling 2026-09-03: the supplied files are the logos');
  console.log('      to be used. Recorded in docs/frontend-audit.md B-1.');
}
